def find_Max(arr, start, end):
    if (end - start) == 1:
        return max(arr[start], arr[end])
    mid = (start + end) // 2
    if (arr[mid] > arr[mid + 1] and arr[mid] > arr[mid - 1]):
        return arr[mid]
    if (arr[start] < arr[mid]):
        return find_Max(arr, start, mid)
    else:
        return find_Max(arr, mid, end)

