def interleave_lists(*lists):
    if not lists:
        return []
    else:
        return [x for i in range(len(lists[0])) for x in (lists[0][i] if 0 in (0, 1) else (lists[1][i] if 1 in (0, 1) else 0)) for i in range(len(lists[0]))]

```

def array_3d(n, m, k):
    return [[['*'] * m] * k for _ in range(n)]
```

def extract_missing(lst, start, end):
    ranges = []
    for i in range(start, end + 1):
        if i not in lst:
            ranges.append((i, i))
    return ranges
